window.kbPageData["views/entry/k-85e833398dfbf081"] = {"key":"entry/k-85e833398dfbf081","state":{"route":"entry/k-85e833398dfbf081"},"node":{"id":"k-85e833398dfbf081","mode":"k","title":"超长期特别国债","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"directorySummary":"4.超长期特别国债\n超长期特别国债，包含三个关键词，超长期、特别、国债。\n超长期，指的是期限。在债券市场上，一般认为发行期限在 10 年以上的利率债为“超\n长期债券”。和普通国债相比，超长期债券能够缓解中短期偿债压力，以时间换空间。\n特别，说的是资金用途。它是为特定目标发行的、具有明确用途的国债，资…","sources":[{"id":"3cf134cec16fa339","label":"超长期特别国债","topic":"经济指标与宏观调控","category":"非时政","text":"4.超长期特别国债\n超长期特别国债，包含三个关键词，超长期、特别、国债。\n超长期，指的是期限。在债券市场上，一般认为发行期限在 10 年以上的利率债为“超\n长期债券”。和普通国债相比，超长期债券能够缓解中短期偿债压力，以时间换空间。\n特别，说的是资金用途。它是为特定目标发行的、具有明确用途的国债，资金需要专款\n专用。\n国债，是国家为了筹集财政资金而发行的一种政府债券，具有最高的信用度，被公认为\n是最安全的投资工具。","source":{"doc":"6cbfb01fe723bba64b75","first":23,"last":24,"page":23,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-85e833398dfbf081":[]}};
